\begin{document}
\begin{center}
\textbf{আদর্শ গ্যাসের ধারণা নিয়ে তাপমাত্রা ও উচ্চ চাপে কাজ করে না, যেহেতু এ অবস্থায় অন্তঃআণবিক বল এবং অণুর আকার - দুটোই প্রভাবশালী হয়ে উঠে। এ ধারণা ভারি গ্যাস (রেফিজারেন্ট) ও তীব্র অন্তঃআণবিক আকর্ষণযুক্ত গ্যাসের (জলীয় বাষ্প) ক্ষেত্রে কার্যকর নয়। উচ্চ চাপে আদর্শ গ্যাস থেকে বাস্তব গ্যাসের আয়তন অনেক বেশি হয়। আবার কম তাপমাত্রায় বাস্তব গ্যাসগুলোর চাপও আদর্শ গ্যাসের তুলনায় অনেক কম।

আদর্শ গ্যাস সূত্রটি মূলত বয়েলের সূত্র ও চার্লসের সূত্রের সমন্বিত রূপ। বাস্তব গ্যাসগুলো কম চাপ ও উচ্চ তাপমাত্রায় প্রায় আদর্শ গ্যাসের মতো আচরণ করে। কম তাপমাত্রা ও উচ্চ চাপে বাস্তব গ্যাসগুলো আদর্শ গ্যাসের আচরণ থেকে সম্পূর্ণ বিচ্ছুত হয়, কারণ এ সময় গ্যাসগুলো অবস্থার পরিবর্তনের মাধ্যমে ঘনীভূত হয়ে তরল কিংবা অবক্ষিত হয়ে কঠিনে পরিণত হয়।

\textbf{আদর্শ গ্যাস সমীকরণ হলো-}

$$PV = nRT$$

যেখানে,

\begin{itemize}
    \item $P$ = গ্যাসের চাপ
    \item $V$ = গ্যাসের আয়তন
    \item $n$ = মোল এককে গ্যাসের পরিমাণ
    \item $R$ = গ্যাস ধ্রুবক $(8.314 \, \text{J} \cdot \text{K}^{-1} \cdot \text{mol}^{-1})$
    \item $T$ = পরম তাপমাত্রা
\end{itemize}
\end{center}
\end{document}

