\section{1787 সালে জ্যাকুইস চার্লস (Jacques Charles) স্থির চাপে গ্যাসের আয়তন ও তাপমাত্রার সম্পর্ক একটি সূত্রের সাহায্যে প্রকাশ করেন।}

\textbf{স্থির চাপে কোনো নিদর্শিত ভরের গ্যাসের আয়তন প্রতি সেলসিয়াস তাপমাত্রা হ্রাস বা বৃদ্ধির জন্য শূন্য ডিগ্রী সেলসিয়াস তাপমাত্রায় এর আয়তনের $\frac{1}{273}$ অংশ হ্রাস বা বৃদ্ধি পায়।}

\textbf{স্থির চাপে কোনো নিদর্শিত ভরের গ্যাসের আয়তন $0^{\circ} \mathrm{C}$ তাপমাত্রায় $V_{0}$ হলে, চার্লসের সূত্রানুসারে-}

\begin{equation}
1^{\circ} \mathrm{C} \text{ তাপমাত্রায় আয়তন } = V_{0} + \frac{1}{273} V_{0}
\end{equation}

\begin{equation}
2^{\circ} \mathrm{C} \text{ তাপমাত্রায় আয়তন } = V_{0} + \frac{2}{273} V_{0}
\end{equation}

\begin{equation}
\therefore \theta^{\circ} \mathrm{C} \text{ তাপমাত্রায় আয়তন, } V = V_{0} + \frac{\theta}{273} V_{0}
\end{equation}

\begin{equation}
V = V_{0} \left(1 + \frac{\theta}{273}\right)
\end{equation}

\textbf{গ্যাসের চাপ স্থির রেখে নিদর্শিত ভরের গ্যাসের তাপমাত্রা পরিবর্তিত করা হলে এর আয়তন পরিবর্তিত হয়, যা চার্লসের সূত্র মেনে চলে। সূত্রাংশ, চার্লসের সূত্রানুসারে স্থির চাপে নিদর্শিত ভরের গ্যাসের তাপমাত্রার সাথে আয়তনের পরিবর্তনের লেখ অঙ্কন করা হলে 10.3 নং চিত্রানুযায়ী একটি লেখচিত্র পাওয়া যাবে। লেখচিত্রটিকে পিছনের দিকে বর্ধিত করা হলে তা তাপমাত্রা অক্ষকে $-273^{\circ} \mathrm{C}$ বিন্দুতে ছেদ করে। অর্থাৎ স্থির চাপে $-273^{\circ} \mathrm{C}$ তাপমাত্রায় গ্যাসের আয়তন শূন্য হবে। 10.3 নং সমীকরণেও $\theta = -273^{\circ} \mathrm{C}$ বসালে $V = 0$ হয়।

