\text{বা, } h\rho g &= 5P - P = 4P \\
\text{বা, } h\rho g &= 4 \times 10^{5} \text{ Pa} \\
\therefore h &= \frac{4 \times 10^{5} \text{ Pa}}{(10^{3} \text{ kg}\cdot\text{m}^{-3}) (9.8 \text{ m}\cdot\text{s}^{-2})} \\
&= 40.82 \text{ m}
\end{align*}

\subsection{উদাহরণ-১০. একজন ডুবুরী কোনো বিশৃঙ্খল পানির স্রদে 20 m গভীর পানিতে কাজ করার সময় 0.000003 m\(^{3}\) আয়তনের বাতাসের বুদবুদ ওপরের দিকে প্রবাহিত হয়। বায়ুমণ্ডলের চাপ 98000 N\(\cdot\)m\(^{-2}\) হলে, পানির উপরিতলে পৌঁছালে প্রতিটি বুদবুদের আয়তন কত হবে? (পানির তাপমাত্রা সর্বত্র সমান ধরো)।}

বয়েলের সূত্র থেকে আমরা জানি,

\begin{align*}
P_{1}V_{1} &= P_{2}V_{2} \\
(P + h\rho g)V_{1} &= PV_{2} \\
\therefore V_{2} &= \frac{P_{1}V_{1}}{P_{2}} = \frac{(P + h\rho g)V_{1}}{P} \\
&= \frac{(98000 + 20 \times 1000 \times 9.8) \times 0.000003}{98000} \\
&= \frac{(98000 + 196000) \times 0.000003}{98000} \\
&= \frac{294000 \times 0.000003}{98000} \\
&= 0.000009 \text{ m}^{3}
\end{align*}

এখানে,

\begin{itemize}
    \item পানির গভীরতা, \(h = 20 \text{ m}\)
    \item পানির তলদেশে বুদবুদের আয়তন, \(V_{1} = 0.000003 \text{ m}^{3}\)
    \item বায়ুমণ্ডলের চাপ, \(P = 98000 \text{ N}\cdot\text{m}^{-2}\)
    \item পানির তলদেশে মোট চাপ,
    \begin{align*}
    P_{1} &= \text{বায়ুমণ্ডলের চাপ} + \text{পানির চাপ} = P + h\rho g \\
    \text{পানির উপরিতলে চাপ, } P_{2} &= P
    \end{align*}
    \item পানির ঘনত্ব, \(\rho = 1000 \text{ kg}/\text{m}^{3}\)
\end{itemize}

