\subsubsection{ক. বেলুনে আবদ্ধ বায়ুর অণুসমূহের গতিশক্তির পরিবর্তন নির্ণয় করো।}

\subsubsection{খ. বেলুনটি স্ত্রীর পৃষ্ঠে এসে বিশেষার্থ হওয়ার সম্ভাবনা গণিতিকভাবে বিশ্লেষণ করো।}

\subsubsection{ক. স্ত্রীর তলদেশে চাপ,}
\begin{align*}
P &= P_0 + h\rho g \\
&= (10^5 + 15 \times 1000 \times 9.8) \text{ Pa} \\
&= 2.47 \times 10^5 \text{ Pa}
\end{align*}

এখন, $PV = nRT_1$
\begin{align*}
n &= \frac{PV}{RT_1} = \frac{2.47 \times 10^5 \text{ Pa} \times 2 \times 10^{-3} \text{ m}^3}{8.314 \text{ J}\text{-mol}^{-1}\text{-K}^{-1} \times 281 \text{ K}} \\
&= 0.2115 \text{ mol}
\end{align*}

সুতরাং বেলুনে আবদ্ধ বায়ুর অণুসমূহের গতিশক্তির পরিবর্তন,
\begin{align*}
\Delta E &= E_2 - E_1 \\
&= \frac{3}{2} nRT_2 - \frac{3}{2} nRT_1 = \frac{3}{2} nR (T_2 - T_1) \\
&= \frac{3}{2} \times 0.2115 \text{ mol} \times 8.314 \text{ J}\text{-mol}^{-1}\text{-K}^{-1} \times (303 \text{ K} - 281 \text{ K}) = 58.03 \text{ J}
\end{align*}

\subsubsection{খ. আদর্শ গ্যাসের সমীকরণ থেকে আমরা জানি,}
\begin{align*}
\frac{P_1V_1}{T_1} &= \frac{P_2V_2}{T_2} \\
\therefore V_2 &= \frac{P_1V_1}{T_1} \times \frac{T_2}{P_2} \\
&= \frac{(2.47 \times 10^5 \text{ Pa})(2 \text{ L})}{281 \text{ K}} \times \frac{303 \text{ K}}{10^5 \text{ Pa}}
\end{align*}

\subsubsection{এখানে,}
\begin{itemize}
\item পানির তলদেশে চাপ, $P_1 = 2.47 \times 10^5 \text{ Pa}$
\item পানির তলদেশে বায়ুর আয়তন, $V_1 = 2 \text{ L}$
\item পানির পৃষ্ঠে চাপ, $P_2 = 10^5 \text{ Pa}$
\item পানির তলদেশে বায়ুর প্রাথমিক তাপমাত্রা, $T_1 = 281 \text{ K}$
\item পানির পৃষ্ঠে শেষ তাপমাত্রা, $T_2 = 303 \text{ K}$
\end{itemize}

