    \item $T_{1}$ ও $T_{2}$ দুটি সুরশালাকর যথাক্রমে 480 Hz ও 320 Hz কম্পাঙ্কের শব্দ সৃষ্টি করে। তাদের তরঙ্গ দৈর্ঘ্যের পার্থক্য 2m। তারা উভয়ে 45 dB শব্দ সৃষ্টি করে।
    \begin{enumerate}
        \item পয়সনের অনুপাত কী?
        \item দুই বন্ধুর কৃত কাজ একই হলেও কি ক্ষমতা ভিন্ন হতে পারে—ব্যাখ্যা করো।
        \item উদ্দিপকের শব্দের তীব্রতা কত?
        \item উদ্দিপকের মাধ্যমিক ঘনত্ব কি বায়ুর চেয়ে বেশি—গাণিতিক বিশ্লেষণের মাধ্যমে তোমার মতামত দাও?
    \end{enumerate}
\end{enumerate}

\subsection{উত্তর}

\begin{enumerate}
    \item পয়সনের অনুপাত কী? (উত্তর: 3.16 $\times$ 10$^{-8}$ Wm$^{-2}$)
    \item উদ্দিপকের মাধ্যমিক ঘনত্ব কি বায়ুর চেয়ে বেশি—গাণিতিক বিশ্লেষণের মাধ্যমে তোমার মতামত দাও? (উত্তর: হ্যাঁ, বায়ুর চেয়ে বেশি)
\end{enumerate}

\subsection{অন্যান্য প্রশ্ন}

\begin{enumerate}
    \item আর্দ্রতামাপক যন্ত্র কী?
    \item আপেক্ষিক আর্দ্রতা কাকে বলে?
    \item শিশিরাঙ্ক কাকে বলে?
    \item শিশির কী?
    \item তাপমাত্রার পরম স্কেল কী?
\end{enumerate}

